async fn cmd_telemetry(verbose: bool, json: bool) -> Result<(), CliError> {
    println!("📡 Scanning topology...");
    
    let db = connect_db(crate::persistence::surreal_bridge::find_project_root().as_deref()).await.map_err(|e| CliError::Database(e.to_string()))?;
    let all_monads = get_all_monads(&db).await.map_err(|e| CliError::Database(e.to_string()))?;
    
    let mut ring_map: std::collections::HashMap<u32, Vec<&Monad>> = std::collections::HashMap::new();
    for m in &all_monads {
        ring_map.entry(m.ring).or_default().push(m);
    }
    
    let crystallized = all_monads.len();
    let active = 0;
    
    println!("\n📊 Ecosystem Pulse:");
    println!("  Active (latent): {}", active);
    println!("  Crystallized: {}", crystallized);
    
    let mut ring_stats = Vec::new();
    
    if verbose {
        println!("\n📀 Ring Breakdown:");
        let mut rings: Vec<_> = ring_map.keys().collect();
        rings.sort();
        for ring in rings {
            if let Some(monads) = ring_map.get(ring) {
                println!("  Ring {}: {} monads", ring, monads.len());
                ring_stats.push(RingStatOutput {
                    ring: *ring,
                    monad_count: monads.len(),
                });
            }
        }
    }
    
    print_result(TelemetryOutput {
        active_monads: active,
        crystallized_monads: crystallized,
        ring_stats,
        last_activity: None,
    }, json);
    
    Ok(())
}

pub fn snap_to_nearest_domain(angle: f64) -> String {
    let normalized = ((angle % 360.0) + 360.0) % 360.0;

    match normalized {
        a if (0.0..45.0).contains(&a) || (315.0..360.0).contains(&a) => "Core".to_string(),
        a if (45.0..135.0).contains(&a) => "UI".to_string(),
        a if (135.0..225.0).contains(&a) => "Persistence".to_string(),
        a if (225.0..315.0).contains(&a) => "Network".to_string(),
        _ => "Unknown".to_string(),
    }
}

impl<'de> Deserialize<'de> for OutputStructure {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Helper {
            Simple(String),
            Tagged {
                #[serde(rename = "type")]
                structure_type: String,
                #[serde(default)]
                rings: bool,
                #[serde(default)]
                vectors: bool,
            },
            NestedObj {
                rings: bool,
                vectors: bool,
            },
        }

        match Helper::deserialize(deserializer)? {
            Helper::Simple(s) => match s.to_lowercase().as_str() {
                "flat" => Ok(OutputStructure::Flat),
                "vectordirs" | "vector_dirs" => Ok(OutputStructure::VectorDirs),
                "ringdirs" | "ring_dirs" => Ok(OutputStructure::RingDirs),
                other => Err(serde::de::Error::custom(format!("Unknown output structure string: {}", other))),
            },
            Helper::NestedObj { rings, vectors } => Ok(OutputStructure::Nested { rings, vectors }),
            Helper::Tagged { structure_type, rings, vectors } => {
                match structure_type.to_lowercase().as_str() {
                    "flat" => Ok(OutputStructure::Flat),
                    "vectordirs" | "vector_dirs" => Ok(OutputStructure::VectorDirs),
                    "ringdirs" | "ring_dirs" => Ok(OutputStructure::RingDirs),
                    "nested" => Ok(OutputStructure::Nested { rings, vectors }),
                    other => Err(serde::de::Error::custom(format!("Unknown output structure type: {}", other))),
                }
            }
        }
    }
}

pub async fn distill_from_template_content(
    db: State<'_, crate::persistence::surreal_bridge::SharedDb>,
    template_content: String,
) -> Result<TemplateResult, String> {
    let template: DistillationTemplate = serde_yaml::from_str(&template_content)
        .map_err(|e| format!("Invalid template YAML: {}", e))?;

    let db_conn = db.read().await;
    let engine = crate::template::engine::TemplateEngine::new(db_conn.clone());
    let monads = engine
        .resolve(&template)
        .await
        .map_err(|e| format!("Failed to resolve template: {}", e))?;

    if monads.is_empty() {
        return Err("No monads matched the template criteria.".to_string());
    }

    let source = source_compiler::distill_source_with_adapters(&monads, &template.adapters);
    let monad_names: Vec<String> = monads.iter().map(|m| m.name.clone()).collect();
    let rings: Vec<u32> = monads.iter().map(|m| m.ring).collect();
    let primary_ring = rings.iter().min().copied();

    Ok(TemplateResult {
        source,
        monad_count: monads.len(),
        monad_names,
        rings_included: primary_ring.map(|r| r.to_string()).unwrap_or_default(),
        output_file: template.output.filename,
    })
}

