async fn cmd_echo(ring_id: u32, monad: Option<String>, json: bool) -> Result<(), CliError> {
    println!("🔄 Echoing from Ring {}...", ring_id);

    let db = connect_db(crate::persistence::surreal_bridge::find_project_root().as_deref()).await.map_err(|e| CliError::Database(e.to_string()))?;
    let all = get_all_monads(&db).await.map_err(|e| CliError::Database(e.to_string()))?;

    let source_monads: Vec<_> = if let Some(name) = monad {
        all.iter().filter(|m| m.ring == ring_id && m.name.contains(&name)).collect()
    } else {
        all.iter().filter(|m| m.ring == ring_id).collect()
    };

    let max_ring = all.iter().map(|m| m.ring).max().unwrap_or(0);
    let target_ring = max_ring + 1;

    if source_monads.is_empty() {
        return Err(CliError::MonadNotFound(format!("No monads in ring {}", ring_id)));
    }

    let mut echoed = 0;
    for source in &source_monads {
        let echoed_monad = crate::ontology::monad::Monad {
            id: format!("{}_echo_{}", source.id, target_ring),
            coord: crate::geometry::polar_space::PolarCoord {
                r: target_ring as f64,
                theta: source.coord.theta,
            },
            content: source.content.clone(),
            name: source.name.clone(),
            ring: target_ring,
            kind: source.kind.clone(),
            semantic_hash: source.semantic_hash.clone(),
            line_start: source.line_start,
            line_end: source.line_end,
            language: source.language.clone(),
            is_archived: false,
        };

        insert_and_link(&db, &echoed_monad, Some(&source.id))
            .await
            .map_err(|e| CliError::Database(e.to_string()))?;
        echoed += 1;
    }

    println!("✓ Echoed {} monads to current ring", echoed);
    println!("  From: Ring {} → Ring {}", ring_id, target_ring);

    print_result(EchoOutput2 {
        source_ring: ring_id,
        current_ring: target_ring,
        monads_echoed: source_monads.iter().map(|m| m.name.clone()).collect(),
    }, json);

    Ok(())
}

pub fn identify_deltas_typed(base_set: &[Monad], new_set: &[Monad]) -> Vec<(Monad, DeltaType)> {
    let mut deltas = Vec::new();

    // Detect Added and Modified monads
    for new_monad in new_set {
        let existing = base_set.iter().find(|m| m.name == new_monad.name);

        match existing {
            Some(base_monad) => {
                if has_evolved(base_monad, new_monad) {
                    // Check if it was renamed (same hash, different name handled elsewhere)
                    deltas.push((new_monad.clone(), DeltaType::Modified));
                }
                // else: Unchanged — not a delta
            },
            None => {
                // Check if it might be a rename (same hash exists under different name)
                let renamed_from = base_set.iter().find(|m| {
                    m.semantic_hash == new_monad.semantic_hash && m.name != new_monad.name
                });

                if renamed_from.is_some() {
                    deltas.push((new_monad.clone(), DeltaType::Renamed));
                } else {
                    // Check for potential rename using similarity
                    let potential_rename = base_set.iter()
                        .map(|m| (m, crate::weaver::semantic_diff::SemanticDiff::similarity(m, new_monad)))
                        .filter(|(_, score)| *score > 0.7)
                        .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap());

                    if let Some((old, score)) = potential_rename {
                        println!("  ? Potential rename detected: {} (from {}) with score {:.2}", new_monad.name, old.name, score);
                    }

                    deltas.push((new_monad.clone(), DeltaType::Added));
                }
            }
        }
    }

    // Detect Deleted monads (present in base but absent in new)
    for base_monad in base_set {
        let still_exists = new_set.iter().any(|m| m.name == base_monad.name);
        let was_renamed = new_set.iter().any(|m| {
            m.semantic_hash == base_monad.semantic_hash && m.name != base_monad.name
        });

        if !still_exists && !was_renamed {
            deltas.push((base_monad.clone(), DeltaType::Deleted));
        }
    }

    deltas
}

