impl AdapterEngine {
    pub fn apply_adapters(monads: &[Monad], adapters: &[AdapterConfig]) -> String {
        let mut source = String::new();

        let imports: Vec<_> = adapters
            .iter()
            .filter_map(|a| {
                if let AdapterType::Import { module } = &a.adapter_type {
                    Some(format!("use {};\n", module))
                } else {
                    None
                }
            })
            .collect();

        let import_count = imports.len();
        for import in imports {
            source.push_str(&import);
        }

        if import_count > 0 {
            source.push('\n');
        }

        let wrappers: Vec<_> = adapters
            .iter()
            .filter(|a| matches!(a.adapter_type, AdapterType::Wrapper { .. }))
            .cloned()
            .collect();

        for monad in monads {
            let mut content = if let Some(alias) = Self::get_alias(adapters, &monad.name) {
                monad.content.replace(&monad.name, &alias)
            } else {
                monad.content.clone()
            };

            if !wrappers.is_empty() {
                let temp_monad = Monad {
                    content,
                    ..monad.clone()
                };
                content = Self::apply_wrappers(&temp_monad, &wrappers);
            }

            source.push_str(&content);
            source.push_str("\n\n");
        }

        source
    }

    pub fn resolve_with_adapters(monads: &[Monad], adapters: &[AdapterConfig]) -> String {
        if adapters.is_empty() {
            let mut source = String::new();
            for monad in monads {
                source.push_str(&monad.content);
                source.push_str("\n\n");
            }
            source
        } else {
            Self::apply_adapters(monads, adapters)
        }
    }

    fn get_alias<'a>(adapters: &'a [AdapterConfig], name: &str) -> Option<String> {
        adapters
            .iter()
            .find(|a| a.from == name)
            .and_then(|a| {
                if let AdapterType::Alias { ref new_name } = a.adapter_type {
                    Some(new_name.clone())
                } else {
                    None
                }
            })
    }

    pub fn apply_wrappers(monad: &Monad, wrappers: &[AdapterConfig]) -> String {
        let mut content = monad.content.clone();

        for adapter in wrappers {
            if let AdapterType::Wrapper { before, after } = &adapter.adapter_type {
                if adapter.from == monad.name || adapter.from == "*" {
                    content = format!("{}{}{}", before, content, after);
                }
            }
        }

        content
    }
}

impl<'de> Deserialize<'de> for RingSelector {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Helper {
            Simple(String),
            LevelNum(u32),
            Tagged {
                #[serde(rename = "type")]
                selector_type: String,
                #[serde(default)]
                value: Option<u32>,
                #[serde(default)]
                level: Option<u32>,
                #[serde(default)]
                min: Option<u32>,
                #[serde(default)]
                max: Option<u32>,
            },
            RangeObj {
                min: u32,
                max: u32,
            },
        }

        match Helper::deserialize(deserializer)? {
            Helper::Simple(s) => match s.to_lowercase().as_str() {
                "latest" => Ok(RingSelector::Latest),
                "all" => Ok(RingSelector::All),
                other => {
                    if let Ok(n) = other.parse::<u32>() {
                        Ok(RingSelector::Level(n))
                    } else {
                        Err(serde::de::Error::custom(format!("Unknown ring selector string: {}", other)))
                    }
                }
            },
            Helper::LevelNum(n) => Ok(RingSelector::Level(n)),
            Helper::RangeObj { min, max } => Ok(RingSelector::Range { min, max }),
            Helper::Tagged { selector_type, value, level, min, max } => {
                match selector_type.to_lowercase().as_str() {
                    "latest" => Ok(RingSelector::Latest),
                    "all" => Ok(RingSelector::All),
                    "level" => Ok(RingSelector::Level(value.or(level).unwrap_or(0))),
                    "range" => Ok(RingSelector::Range {
                        min: min.unwrap_or(0),
                        max: max.unwrap_or(u32::MAX),
                    }),
                    other => Err(serde::de::Error::custom(format!("Unknown ring selector type: {}", other))),
                }
            }
        }
    }
}

