pub fn distill_source_with_adapters(monads: &[Monad], adapters: &[AdapterConfig]) -> String {
    if monads.is_empty() {
        return String::new();
    }

    if !adapters.is_empty() {
        return AdapterEngine::apply_adapters(monads, adapters);
    }

    // Group by kind for proper ordering: modules/types first, then impls, then functions
    let ordered = order_by_dependency(monads);

    let mut source = String::new();

    // Distillation header
    let mut rings: Vec<u32> = monads.iter().map(|m| m.ring).collect();
    rings.sort();
    rings.dedup();
    let primary_lang = monads.first().map(|m| m.language.as_str()).unwrap_or("unknown");

    source.push_str(&format!("// Distilled Source — {} monads from {} ring(s)\n", 
        monads.len(), rings.len()
    ));
    source.push_str(&format!("// Language: {}\n\n", primary_lang));

    // Auto-generate imports and mod statements
    if primary_lang == "rust" {
        let mod_statements: Vec<String> = crate::weaver::auto_imports::ImportAnalyzer::generate_mod_statements(monads);
        for stmt in mod_statements.iter() {
            source.push_str(stmt);
            source.push('\n');
        }
        source.push('\n');
    }

    for monad in &ordered {
        source.push_str(&monad.content);
        source.push_str("\n\n");
    }

    source
}

async fn cmd_crystallize(message: &str, file: &str, json: bool) -> Result<(), CliError> {
    println!("💎 Crystallizing: {}", if message.is_empty() { "No message" } else { message });
    
    let source_path = PathBuf::from(file);
    if !source_path.exists() {
        return Err(CliError::ProjectNotFound(format!("File not found: {}", file)));
    }
    
    let source_code = std::fs::read_to_string(&source_path)
        .map_err(|e| CliError::Io(e))?;
    
    let db = connect_db(crate::persistence::surreal_bridge::find_project_root().as_deref()).await.map_err(|e| CliError::Database(e.to_string()))?;
    let all_monads = get_all_monads(&db).await.map_err(|e| CliError::Database(e.to_string()))?;
    let current_max_ring = all_monads.iter().map(|m| m.ring).max().unwrap_or(0);
    let next_ring = current_max_ring + 1;
    
    let new_monads = extract_raw_monads(&source_code, next_ring);
    
    if new_monads.is_empty() {
        println!("⚠ No monads extracted from file");
        return Ok(());
    }
    
    let base_monads = get_ring(&db, current_max_ring).await.ok();
    let deltas = if let Some(ref base) = base_monads {
        crate::weaver::resolver::identify_deltas(base, &new_monads)
    } else {
        new_monads.clone()
    };
    
    let mut added = 0;
    let mut modified = 0;
    
    for monad in &deltas {
        let parent = base_monads.as_ref().and_then(|base| {
            base.iter().find(|m| m.name == monad.name)
        });
        let parent_id = parent.map(|p| p.id.as_str());
        
        insert_and_link(&db, monad, parent_id)
            .await
            .map_err(|e| CliError::Database(e.to_string()))?;
        
        if parent.is_some() {
            modified += 1;
        } else {
            added += 1;
        }
    }
    
    println!("✓ Ring {} created", next_ring);
    println!("  Added: {}", added);
    println!("  Modified: {}", modified);
    
    print_result(CrystallizeOutput {
        new_ring: next_ring,
        monads_added: added,
        monads_modified: modified,
        intent: message.to_string(),
        timestamp: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs(),
    }, json);
    
    Ok(())
}

