fn order_by_dependency(monads: &[Monad]) -> Vec<Monad> {
    let mut sorted = monads.to_vec();
    sorted.sort_by_key(|m| {
        use crate::ontology::monad::MonadKind;
        match m.kind {
            MonadKind::Module => 0,
            MonadKind::Constant => 1,
            MonadKind::TypeAlias => 2,
            MonadKind::Struct => 3,
            MonadKind::Enum => 4,
            MonadKind::Trait => 5,
            MonadKind::Impl => 6,
            MonadKind::Function => 7,
            MonadKind::Unknown => 8,
        }
    });
    sorted
}

