fn extract_ast_tokens(content: &str) -> String {
    let mut tokens = String::with_capacity(content.len());
    let chars: Vec<char> = content.chars().collect();
    let len = chars.len();
    let mut i = 0;

    while i < len {
        let c = chars[i];

        // Skip line comments
        if c == '/' && i + 1 < len && chars[i + 1] == '/' {
            while i < len && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }

        // Skip block comments
        if c == '/' && i + 1 < len && chars[i + 1] == '*' {
            i += 2;
            while i + 1 < len && !(chars[i] == '*' && chars[i + 1] == '/') {
                i += 1;
            }
            i += 2;
            continue;
        }

        // Skip hash comments (Rust, Python, etc.)
        if c == '#' && i + 1 < len && chars[i + 1] == '!' {
            while i < len && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }
        if c == '#' && (i == 0 || chars[i - 1] != '!') {
            while i < len && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }

        // Skip string literal contents but keep delimiters for structure
        if c == '"' || c == '\'' {
            let quote = c;
            i += 1;
            while i < len && chars[i] != quote {
                if chars[i] == '\\' && i + 1 < len {
                    i += 2;
                } else {
                    i += 1;
                }
            }
            if i < len {
                i += 1; // skip closing quote
            }
            tokens.push(quote);
            tokens.push(quote);
            continue;
        }

        // Skip whitespace (collapse multiple into single space)
        if c.is_whitespace() {
            if !tokens.ends_with(' ') && !tokens.is_empty() {
                tokens.push(' ');
            }
            i += 1;
            continue;
        }

        tokens.push(c);
        i += 1;
    }

    // Final trim
    tokens.trim().to_string()
}

