pub async fn cli_vector(angle: f64) -> Result<CliResponse, String> {
    let normalized = angle % 360.0;
    let domain = if normalized < 45.0 || normalized >= 315.0 {
        "CORE"
    } else if normalized < 135.0 {
        "UI"
    } else if normalized < 225.0 {
        "PERSISTENCE"
    } else {
        "NETWORK"
    };

    let output = format!("📐 Vector opened: {} ({:.1}°)", domain, normalized);

    Ok(CliResponse { success: true, output, error: None })
}

pub async fn distill_from_template(
    db: State<'_, crate::persistence::surreal_bridge::SharedDb>,
    template_path: String,
) -> Result<String, String> {
    let template_content = std::fs::read_to_string(&template_path)
        .map_err(|e| format!("Failed to read template: {}", e))?;

    let template: DistillationTemplate = serde_yaml::from_str(&template_content)
        .map_err(|e| format!("Failed to parse template: {}", e))?;

    let db_conn = db.read().await;
    let engine = crate::template::engine::TemplateEngine::new(db_conn.clone());
    let monads = engine
        .resolve(&template)
        .await
        .map_err(|e| format!("Failed to resolve template: {}", e))?;

    if monads.is_empty() {
        return Err("No monads matched the template criteria.".to_string());
    }

    let source = source_compiler::distill_source_with_adapters(&monads, &template.adapters);

    Ok(source)
}

